<?php
namespace App\Http\Controllers;
use App\Models\{ApprenticeIntakeBatch as Batch,Programme,Employer,TutorGroup,User};
use App\Support\{ApprenticeIntakes as Intakes,LearningAccess,StaffHandover};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class ApprenticeIntakeController extends Controller {
 private function manager(Request $r):void {abort_unless(LearningAccess::manager($r->user()),403);}
 private function view(string $v,array $d=[]) {return response()->view('intakes.'.$v,$d)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 public function index(Request $r) {$this->manager($r);$r->validate(['page'=>['nullable','integer','min:1']]);return $this->view('index',['batches'=>Batch::orderByDesc('created_at')->orderByDesc('id')->paginate(20)]);}
 public function form(Request $r) {$this->manager($r);return $this->view('form');}
 public function template(Request $r) {$this->manager($r);return response(implode(',',Intakes::HEADERS)."\n",200,['Content-Type'=>'text/csv; charset=UTF-8','Content-Disposition'=>'attachment; filename="GTA-Apprentice-Intake.csv"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 public function preview(Request $r) {$this->manager($r);$d=$r->validate(['file'=>['required','file','extensions:csv','max:489'],'request_token'=>['required','uuid'],'title'=>['required','string','max:160'],'reference'=>['required','string','max:2000'],'confirmed'=>['accepted']]);$b=Intakes::prepare($r->user(),(int)$r->session()->get('auth_version'),$d['request_token'],file_get_contents($r->file('file')->getRealPath()),$d['title'],$d['reference']);return to_route('intakes.show',$b)->with('status','Intake preview saved. No profiles/accounts/tasks created. Correct row errors in a fresh file; another manager checks valid rows before whole-batch application.');}
 public function show(Request $r,Batch $intake) {$this->manager($r);abort_unless(Intakes::intact($intake),409,'Intake evidence cannot be verified.');return $this->view('show',['batch'=>$intake,'source'=>$intake->source,'fresh'=>Intakes::fresh($intake),'applied'=>Intakes::applied($intake),'cohort'=>Intakes::cohort($intake),'events'=>DB::table('apprentice_intake_events')->where('batch_id',$intake->id)->orderBy('id')->get(['event','actor_id','record_version','created_at'])]);}
 public function decide(Request $r,Batch $intake) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'decision'=>['required','in:apply,reject,withdraw'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Intakes::decide($r->user(),(int)$r->session()->get('auth_version'),$intake,(int)$d['version'],$d['decision'],$d['note']);return back()->with('status','Intake decision saved. Profile creation does not invite accounts, allocate tasks or establish induction/funding eligibility.');}
 public function catalogue(Request $r) {$this->manager($r);$d=$r->validate(['kind'=>['nullable','in:programmes,employers,groups,staff'],'search'=>['nullable','string','max:100'],'page'=>['nullable','integer','min:1']]);$kind=$d['kind']??'programmes';$search=trim($d['search']??'');$class=['programmes'=>Programme::class,'employers'=>Employer::class,'groups'=>TutorGroup::class,'staff'=>User::class][$kind];$q=$class::where('active',true);if($search!==''){$needle='%'.str_replace(['!','%','_'],['!!','!%','!_'],mb_strtolower($search)).'%';$q->whereRaw("LOWER(name) LIKE ? ESCAPE '!'",[$needle]);}if($kind==='staff'){$q->whereIn('role',\App\Support\DirectoryCatalog::STAFF_ROLES);}$records=$q->orderBy('name')->orderBy('id')->paginate(50)->withQueryString();return $this->view('catalogue',compact('kind','search','records'));}
 public function report(Request $r,Batch $intake) {$this->manager($r);abort_unless(Intakes::intact($intake),409);$cohort=array_map(fn($r)=>collect($r)->only(['id','reference','current','issues','tasks','account_state'])->all(),Intakes::cohort($intake));return response()->json(['batch_id'=>$intake->id,'state'=>$intake->state,'applied_proof_verified'=>Intakes::applied($intake),'rows'=>array_map(fn($row)=>['line'=>$row['line'],'reference'=>$row['input']['reference'],'errors'=>$row['errors'],'warnings'=>$row['warnings']],$intake->source['rows']),'current_setup'=>$cohort,'private_source_names_emails_and_notes_exported'=>false,'automatic_messages_sent'=>false,'production_approved'=>false],200,['Content-Disposition'=>'attachment; filename="GTA-Intake-Setup-Report.json"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
}
